package glitch

import data.glitch_lib

# Security-sensitive contexts where missing fallback is critical
security_sensitive_attrs := {
    "principal", "permission", "role", "access_level", "authorization",
    "encryption_type", "kms_key", "tls_version", "cipher_suite",
    "security_group_rule", "firewall_rule", "cidr_block", "port_range",
    "auth_method", "identity_provider", "credential_type",
    "log_destination", "retention_policy", "compliance_standard",
    "policy", "effect", "action", "resource"
}

# External input sources
external_input_indicators := {"var", "variable", "param", "parameter", "input", "argument", "lookup"}

# Check if value originates from external input
is_external_input(node) {
    walk(node, [_, n])
    n.ir_type == "VariableReference"
    regex.match("^(var\\.|@|\\$)", n.value)
} else {
    walk(node, [_, n])
    n.ir_type == "FunctionCall"
    n.name in external_input_indicators
} else {
    walk(node, [_, n])
    n.ir_type == "MethodCall"
    regex.match("^(lookup|dig|fetch)", n.method)
}

# Check if conditional has explicit branches without fallback
has_multiple_branches_no_fallback(cond) {
    count_branches(cond, 0) >= 2
    not has_fallback_branch(cond)
}

count_branches(cond, acc) = total {
    cond.else_statement != null
    new_acc := acc + 1
    total := count_branches(cond.else_statement, new_acc)
} else = total {
    cond.is_default == false
    total := acc + 1
} else = total {
    total := acc
}

has_fallback_branch(cond) {
    cond.is_default == true
} else {
    cond.else_statement != null
    cond.else_statement.is_default == true
} else {
    cond.else_statement != null
    has_fallback_branch(cond.else_statement)
}

# Check if conditional output flows to security-sensitive context
flows_to_security_context(cond, parent) {
    # Check if condition variable is used in security-sensitive attribute
    walk(parent, [_, n])
    n.ir_type == "Attribute"
    lower(n.name) in security_sensitive_attrs
    shares_variable_reference(cond.condition, n.value)
}

# Check if two nodes share a variable reference
shares_variable_reference(node1, node2) {
    vars1 := {v | walk(node1, [_, v]); v.ir_type == "VariableReference"}
    vars2 := {v | walk(node2, [_, v]); v.ir_type == "VariableReference"}
    count(vars1 & vars2) > 0
}

# Check if conditional result is used in security-sensitive assignment
conditional_output_security_sensitive(cond, parent) {
    walk(parent, [_, n])
    n.ir_type == "Assign"
    uses_conditional_result(n, cond)
    is_security_sensitive_target(n.left)
}

uses_conditional_result(node, cond) {
    walk(node, [_, n])
    n.ir_type == "ConditionalStatement"
    n == cond
}

is_security_sensitive_target(node) {
    walk(node, [_, n])
    n.ir_type == "VariableReference"
} else {
    walk(parent_scope, [_, n])
    n.ir_type == "Attribute"
    lower(n.name) in security_sensitive_attrs
}

# Check for no validation around conditional
no_validation_around(cond, parent) {
    not has_pre_validation(cond, parent)
    not has_post_validation(cond, parent)
}

has_pre_validation(cond, parent) {
    walk(parent, [_, n])
    n.ir_type in {"ConditionalStatement", "FunctionCall"}
    n != cond
    validates_input(n, cond.condition)
}

has_post_validation(cond, parent) {
    walk(parent, [_, n])
    n.ir_type in {"ConditionalStatement", "FunctionCall"}
    validates_output(n, cond)
}

validates_input(validator, target) {
    # Simple check: validator contains reference to same variable
    shares_variable_reference(validator, target)
}

validates_output(validator, cond) {
    # Simple check: validator references conditional result
    uses_conditional_result(validator, cond)
}

Glitch_Analysis[result] {
    # Find all conditional statements in the IR
    walk(input, [path, cond])
    cond.ir_type == "ConditionalStatement"
    cond.type in {"IF", "SWITCH"}

    # Get parent context
    parent := glitch_lib._gather_parent_unit_blocks[_]

    # Check: multiple branches without fallback
    has_multiple_branches_no_fallback(cond)

    # Check: input originates from external source  
    is_external_input(cond.condition)

    # Check: output flows to security context
    flows_to_security_context(cond, parent)

    # Check: no validation around
    no_validation_around(cond, parent)

    result := {
        "type": "sec_no_default_switch",
        "element": cond,
        "path": parent.path,
        "description": "Missing default case in multi-branch conditional - Conditional statements without a fallback/default branch may allow unexpected values to propagate to security-sensitive configurations. (CWE-478)"
    }
}

