package glitch

import data.glitch_lib

is_external_input(node) {
    walk(node, [_, n])
    n.ir_type == "VariableReference"
} else {
    walk(node, [_, n])
    n.ir_type == "FunctionCall"
} else {
    walk(node, [_, n])
    n.ir_type == "MethodCall"
} else {
    # Handle Access nodes (e.g., node["key"] or node.key)
    walk(node, [_, n])
    n.ir_type == "Access"
}

has_default_branch(cond) {
    walk(cond, [_, n])
    n.ir_type == "ConditionalStatement"
    n.is_default == true
}

# Count all non-default branches in the chain
count_nondefault_branches(cond) = n {
    n := count({b |
        walk(cond, [_, b])
        b.ir_type == "ConditionalStatement"
        b.is_default == false
    })
}

# Check if this is a SWITCH with multiple branches AND no default
is_vulnerable_switch_pattern(cond) {
    cond.type == "SWITCH"
    count_nondefault_branches(cond) >= 2
    not has_default_branch(cond)
}

security_sensitive_attr(name) {
    lower(name) == "mode"
} else {
    lower(name) == "owner"
} else {
    lower(name) == "group"
} else {
    lower(name) == "user"
} else {
    lower(name) == "ensure"
} else {
    lower(name) == "action"
} else {
    regex.match("(?i)(permission|access|auth|encrypt|ssl|tls|password|credential|key|cert)", name)
}

attribute_has_security_relevance(au) {
    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]
    security_sensitive_attr(attr.name)
}

variable_used_in_security_context(varname, parent) {
    walk(parent, [_, n])
    n.ir_type == "AtomicUnit"
    attribute_has_security_relevance(n)
    attrs := glitch_lib.all_attributes(n)
    attr := attrs[_]
    walk(attr.value, [_, v])
    v.ir_type == "VariableReference"
    v.value == varname
}

branches_affect_security_config(cond, parent) {
    # Find variables assigned in branches that are used in security contexts
    walk(cond, [_, branch_stmt])
    branch_stmt.ir_type == "Variable"
    variable_used_in_security_context(branch_stmt.name, parent)
} else {
    # Direct AtomicUnits in branches with security-sensitive attrs
    walk(cond, [_, branch_stmt])
    branch_stmt.ir_type == "AtomicUnit"
    attribute_has_security_relevance(branch_stmt)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    walk(parent, [path, cond])
    cond.ir_type == "ConditionalStatement"

    # Only flag SWITCH types (not IF) that match the vulnerable pattern
    is_vulnerable_switch_pattern(cond)

    # Must have external input driving the condition
    is_external_input(cond.condition)

    # Must affect security-sensitive configuration
    branches_affect_security_config(cond, parent)

    result := {
        "type": "sec_no_default_switch",
